<?php
return static function(PDO $p):void {
    \EPejabat\Core\Core::tx($p,static function()use($p){
        foreach(['core'=>['Shared Core','active','/dashboard'],'training'=>['Training, Attendance & CPD','inactive',null],'eforms'=>['e-Forms','inactive',null]] as $k=>$v)\EPejabat\Core\Database::query($p,'INSERT INTO module_registry(module_key,name,status,navigation_path,permission_namespace) VALUES(?,?,?,?,?)',[$k,$v[0],$v[1],$v[2],$k]);
        foreach(['national'=>'Malaysia / National','state'=>'State','pkd'=>'PKD','clinic'=>'Clinic / Facility','facility'=>'Other Facility','unit'=>'Unit'] as $k=>$v)\EPejabat\Core\Database::query($p,"INSERT INTO master_data(category,code,name) VALUES('organisation_type',?,?)",[$k,$v]);
        $p->exec("UPDATE organisations o JOIN master_data m ON m.category='organisation_type' AND m.code=o.type SET o.type_id=m.id");
        $p->exec('UPDATE staff_profiles p JOIN users u ON u.staff_identity_id=p.staff_identity_id SET p.official_email=LOWER(TRIM(u.email)),p.updated_at=p.updated_at');
        foreach(['active'=>'Active','inactive'=>'Inactive','retired'=>'Retired','transferred'=>'Transferred'] as $k=>$v)\EPejabat\Core\Database::query($p,"INSERT INTO master_data(category,code,name) VALUES('employment_status',?,?)",[$k,$v]);
        $codes=['core.dashboard.view','core.organisations.manage','core.users.manage','core.audit.view','core.settings.manage','core.migrations.manage','core.staff.view','core.staff.manage','core.profile.self','core.registry.import','core.registrations.review','core.roles.manage','core.master.manage','core.notifications.self','core.notifications.manage','core.documents.upload','core.documents.view','core.documents.manage','core.identification.view','core.modules.manage'];
        foreach($codes as $c){\EPejabat\Core\Database::query($p,'INSERT INTO permissions(code,module_code,name) VALUES(?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)',[$c,'core',$c]);}
        $roles=['pkd_admin','clinic_admin','unit_admin','staff'];
        foreach($roles as $r)\EPejabat\Core\Database::query($p,'INSERT INTO roles(code,name,module_code,is_system) VALUES(?,?,?,1)',[$r,ucwords(str_replace('_',' ',$r)),'core']);
        $p->exec("INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='super_admin' AND p.module_code='core'");
        foreach($roles as $r){$list=$r==='staff'?['core.dashboard.view','core.profile.self','core.notifications.self','core.documents.upload','core.documents.view']:['core.dashboard.view','core.staff.view','core.staff.manage','core.users.manage','core.profile.self','core.registry.import','core.registrations.review','core.roles.manage','core.notifications.self','core.documents.upload','core.documents.view','core.documents.manage','core.organisations.manage'];foreach($list as $c)\EPejabat\Core\Database::query($p,'INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code=? AND p.code=?',[$r,$c]);}
        foreach(['activation'=>['Aktifkan akaun epejabat','Sila buka pautan pengesahan: {{url}}\nPautan tamat tempoh dalam 60 minit.'],'reset'=>['Tetapkan semula kata laluan','Sila buka pautan: {{url}}\nPautan tamat tempoh dalam 60 minit.'],'correction'=>['Pembetulan permohonan','Sila semak permohonan melalui pautan: {{url}}\nPautan tamat tempoh dalam 60 minit.'],'system'=>['Notifikasi epejabat','{{message}}']] as $k=>$v)\EPejabat\Core\Database::query($p,'INSERT INTO notification_templates(template_key,subject,body) VALUES(?,?,?)',[$k,$v[0],str_replace('\\n',"\n",$v[1])]);
        $admin=(int)$p->query("SELECT a.user_id FROM user_role_assignments a JOIN roles r ON r.id=a.role_id WHERE r.code='super_admin' AND a.organisation_id IS NULL LIMIT 1")->fetchColumn();
        \EPejabat\Core\Database::query($p,"INSERT INTO employment_history(staff_identity_id,organisation_id,change_reason,changed_by) SELECT staff_identity_id,organisation_id,'Phase 0 baseline; previous effective date unknown',? FROM staff_profiles",[$admin]);
    });
};
